const payload = typeof $input.item.json.body === 'string'
  ? JSON.parse($input.item.json.body)
  : $input.item.json;

if (!payload.inspection_id) {
  throw new Error('Missing required field: inspection_id');
}

const passed = payload.result === 'pass' || payload.passed === true;

return [{
  json: {
    inspection_id: payload.inspection_id,
    equipment_id: payload.equipment_id,
    facility_id: payload.facility_id,
    result: payload.result || (passed ? 'pass' : 'fail'),
    passed: passed,
    result_label: passed ? 'PASSED' : 'FAILED',
    inspector_id: payload.inspector_id || null,
    inspector_name: payload.inspector_name || 'Unknown Inspector',
    completed_at: payload.completed_at || new Date().toISOString(),
    notes: payload.notes || '',
    deficiencies: payload.deficiencies || [],
    deficiency_count: (payload.deficiencies || []).length,
    next_due_date: payload.next_due_date || null
  }
}];

const inspection = $('Extract Inspection Results').item.json;
const facility = $input.item.json;

let deficiencySection = '';
if (!inspection.passed && inspection.deficiency_count > 0) {
  const list = (inspection.deficiencies || []).map((d, i) => `  ${i + 1}. ${d}`).join('
');
  deficiencySection = `
--- DEFICIENCIES FOUND (${inspection.deficiency_count}) ---
${list}
`;
}

let nextDueSection = '';
if (inspection.next_due_date) {
  nextDueSection = `
Next Scheduled Inspection: ${inspection.next_due_date}`;
}

const body = `Dear ${facility.admin_name},

An inspection has been completed at ${facility.facility_name}. Below is the summary.

--- INSPECTION RESULT: ${inspection.result_label} ---
Inspection ID:   ${inspection.inspection_id}
Completed At:    ${inspection.completed_at}
Inspector:       ${inspection.inspector_name}

--- EQUIPMENT ---
Type:            ${facility.equipment_type}
Model:           ${facility.model_number}
Serial Number:   ${facility.serial_number}
${deficiencySection}${nextDueSection}
${inspection.notes ? `--- NOTES ---
${inspection.notes}
` : ''}
${!inspection.passed ? 'Action Required: This equipment has failed inspection. Please review the deficiencies above and coordinate corrective action before placing this equipment back in service.
' : ''}
View the full inspection report in ZipSafe:
https://zipsafe.2h2.us

ZipSafe Platform`;

return [{
  json: {
    ...facility,
    ...inspection,
    email_body: body
  }
}];
